content.process:
catalog = get_plugin('DatasetCatalog')
agent_id = (state.get('agent_id') or state.get('runner_id') or 'wf_chemdisgene_re_llm_linear').strip()
fmt = (state.get('format') or 're').strip()
source = (state.get('source') or 'data/raw/chemdisgene.txt').strip()
output_name = (state.get('output_name') or '').strip() or None
mirror_agent = (state.get('mirror_agent_id') or '').strip()
mirror_fmt = (state.get('mirror_format') or 'ner').strip()
mirror = [{'agent_id': mirror_agent, 'format': mirror_fmt}] if mirror_agent else None
if not catalog:
    __result__ = {'error': 'DatasetCatalog plugin unavailable'}
else:
    try:
        __result__ = catalog.build_full(
            agent_id,
            source=source,
            format=fmt,
            output_name=output_name,
            mirror=mirror,
        )
    except Exception as e:
        __result__ = {'error': str(e), 'agent_id': agent_id, 'source': source}
